mapper.select:
SELECT 

 WHERE flt03_company_id = #{companyId}
   AND flt03_person_id = #{personId}
   AND flt03_account_id NOT IN (
           SELECT flt06_account_id
             FROM flt06_account_close
                  INNER JOIN flt03_account ON flt03_account_id = flt06_account_id
            WHERE flt03_person_id = #{personId}
       )
 ORDER BY flt03_setup_date, sys15_corp_nm collate "ko_KR.utf8" asc, TO_DECRYPTS(flt03_account_no)

